<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">agileplus</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">feature-i</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>
